'use server'

import { revalidatePath } from 'next/cache'

// Simulated database state
// In a real app, this would be a database call
let notificationsEnabled = false

export async function getNotificationPreference() {
  return notificationsEnabled
}

export async function toggleNotifications() {
  // Toggle the value
  notificationsEnabled = !notificationsEnabled

  // Revalidate the home path to refresh the data on the page
  revalidatePath('/')
}

import { getNotificationPreference, toggleNotifications } from './actions'

export default async function Home() {
  const isEnabled = await getNotificationPreference()

  return (
    <main style={{ padding: '2rem', fontFamily: 'system-ui, sans-serif' }}>
      <h1>Settings</h1>
      <div style={{ marginBottom: '1rem' }}>
        Status: <strong>{isEnabled ? 'ON' : 'OFF'}</strong>
      </div>

      <form action={toggleNotifications}>
        <button 
          type="submit"
          style={{
            padding: '8px 16px',
            backgroundColor: isEnabled ? '#ff4444' : '#0070f3',
            color: 'white',
            border: 'none',
            borderRadius: '4px',
            cursor: 'pointer'
          }}
        >
          {isEnabled ? 'Disable' : 'Enable'} Notifications
        </button>
      </form>
    </main>
  );
}

